9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	} as const satisfies Record<string, number>;
15	
16	type InsurableItemType = keyof typeof BASE_PREMIUMS;
17	
18	type Item = {
19	  type: InsurableItemType;
20	};
21	
22	type QuoteStep = {
23	  op: "quote";
24	  items: Item[];
25	};
26	
27	type Customer = {
28	  yearsWithMHPCO: number;
29	};
30	
31	type Scenario = {
32	  customer: Customer;
33	  steps: QuoteStep[];
34	};
35	
36	const PROCESSING_FEE = 5;
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	const percentOf = (amount: number, percent: number): number =>
40	  (amount * percent) / 100;
41	
42	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
43	
44	const policyBasePremiumOf = (items: Item[]): number =>
45	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
46	
47	const quote = (step: QuoteStep): QuoteResult => {
48	  const basePremium = policyBasePremiumOf(step.items);
49	  const firstInsuranceSurcharge = percentOf(
50	    basePremium,
51	    FIRST_INSURANCE_SURCHARGE_PERCENT,
52	  );
53	
54	  return {
55	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
56	  };
57	};
58	
59	export const runScenario = (scenario: Scenario): ScenarioResult => {
60	  return { results: scenario.steps.map(quote) };
61	};
