const initialAssessmentSurcharge = percentOf(
  basePremium,
  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
);

return {
  premium: roundedInMHPCOsFavour(
    basePremium + initialAssessmentSurcharge + PROCESSING_FEE,
  ),
};

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

// The MHPCO always rounds in its own favour: premiums (which the customer
// pays) go up, payouts (which the MHPCO pays) go down.
const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
